use super::{effect_budget::*,authority::{Authority,Failure},authority_store::Fault,admission_tests::{Fixture,evidence},authority_tests::{root,queued},lease_controller::{Controller,Validity},model::*,store::nonce};
use crate::chat::Chat;use std::sync::Arc;
fn setup(provider:&str)->(Fixture,Authority,Record,super::lease_controller::Pending,super::lease_controller::Owned){
 let f=Fixture::new();let a=Authority::ensure(&root(&f)).unwrap();let g=queued(&f,&f.goal(provider),&a);let main=Chat::persistent(f.path.join("live.json"));let c=Controller::new().unwrap();let p=c.prepare(&g,&root(&f),&f.path.join("contexts"),&main,&evidence(&g,100_006),"claim".into(),100_006,Arc::new(|_,_,_|Validity::Current)).unwrap();let(r,o)=p.claim(&f.store(),&a,&evidence(&g,100_007),100_007).unwrap();(f,a,r.record,p,o.unwrap())
}
fn attempt(request:&str,kind:Kind,output:u64)->Attempt{Attempt{id:nonce().unwrap(),request_id:request.into(),input_hash:"a".repeat(64),kind,output_reserved:output,phase:Phase::Reserved,accepted_output:None,reserved_at:100_008,started_at:None,finished_at:None}}
macro_rules! invoke{($a:expr,$g:expr,$o:expr,$method:ident,$($args:expr),*)=>{{$a.$method(&$g.admissions[0].spec,$g.admissions[0].proof.as_ref().unwrap(),$o.lease(),$($args),*)}}}
#[test]fn model_and_tool_attempts_consume_separate_original_counts(){let(_f,a,g,_p,o)=setup("codex");for n in 0..3{invoke!(a,g,o,reserve_attempt,&attempt(&format!("m{n}"),Kind::Model,1),100_009).unwrap();}assert_eq!(invoke!(a,g,o,reserve_attempt,&attempt("m3",Kind::Model,1),100_009).err(),Some(Failure::Capacity));for n in 0..2{invoke!(a,g,o,reserve_attempt,&attempt(&format!("t{n}"),Kind::Tool,1),100_009).unwrap();}assert_eq!(invoke!(a,g,o,reserve_attempt,&attempt("t2",Kind::Tool,1),100_009).err(),Some(Failure::Capacity));}
#[test]fn output_budget_is_reserved_before_start_and_unknown_usage_never_frees_it(){let(_f,a,g,_p,o)=setup("ollama");let call=attempt("first",Kind::Model,4096);invoke!(a,g,o,reserve_attempt,&call,100_009).unwrap();assert_eq!(invoke!(a,g,o,output_remaining,100_009).unwrap(),0);invoke!(a,g,o,start_attempt,&call,100_010).unwrap();invoke!(a,g,o,finish_attempt,&call,None,100_011).unwrap();assert_eq!(invoke!(a,g,o,output_remaining,100_012).unwrap(),0);assert_eq!(invoke!(a,g,o,reserve_attempt,&attempt("next",Kind::Model,1),100_012).err(),Some(Failure::Capacity));}
#[test]fn known_complete_receipt_releases_only_unused_output_not_the_call_count(){let(_f,a,g,_p,o)=setup("ollama");let call=attempt("first",Kind::Model,4096);invoke!(a,g,o,reserve_attempt,&call,100_009).unwrap();invoke!(a,g,o,start_attempt,&call,100_010).unwrap();invoke!(a,g,o,finish_attempt,&call,Some(37),100_011).unwrap();assert_eq!(invoke!(a,g,o,output_remaining,100_012).unwrap(),4059);assert_eq!(invoke!(a,g,o,start_attempt,&call,100_012).err(),Some(Failure::RecoveryRequired));}
#[test]fn original_unstarted_reservation_reconciles_lost_ack_without_a_second_charge(){let(_f,mut a,g,_p,o)=setup("codex");let call=attempt("first",Kind::Model,2048);a.fault=Fault::AfterGrantPublish;assert_eq!(invoke!(a,g,o,reserve_attempt,&call,100_009).err(),Some(Failure::Uncertain));a.fault=Fault::None;invoke!(a,g,o,reserve_attempt,&call,100_010).unwrap();assert_eq!(invoke!(a,g,o,output_remaining,100_010).unwrap(),2048);invoke!(a,g,o,start_attempt,&call,100_011).unwrap();assert_eq!(invoke!(a,g,o,reserve_attempt,&call,100_012).err(),Some(Failure::RecoveryRequired));}
#[test]fn started_or_settled_attempt_is_never_a_replayable_effect(){let(_f,mut a,g,_p,o)=setup("codex");let call=attempt("first",Kind::Model,10);invoke!(a,g,o,reserve_attempt,&call,100_009).unwrap();a.fault=Fault::AfterGrantPublish;assert_eq!(invoke!(a,g,o,start_attempt,&call,100_010).err(),Some(Failure::Uncertain));a.fault=Fault::None;assert_eq!(invoke!(a,g,o,start_attempt,&call,100_011).err(),Some(Failure::RecoveryRequired));invoke!(a,g,o,finish_attempt,&call,None,100_012).unwrap();assert_eq!(invoke!(a,g,o,start_attempt,&call,100_013).err(),Some(Failure::RecoveryRequired));}
#[test]fn another_pending_object_cannot_adopt_the_same_logical_request(){let(_f,a,g,_p,o)=setup("codex");let first=attempt("first",Kind::Model,100);invoke!(a,g,o,reserve_attempt,&first,100_009).unwrap();let other=attempt("first",Kind::Model,100);assert_eq!(invoke!(a,g,o,reserve_attempt,&other,100_010).err(),Some(Failure::RecoveryRequired));let mut changed=first.clone();changed.input_hash="b".repeat(64);assert_eq!(invoke!(a,g,o,reserve_attempt,&changed,100_010).err(),Some(Failure::RecoveryRequired));}
#[test]fn stop_and_expiry_block_new_io_but_allow_original_receipt_to_be_preserved(){let(_f,a,g,_p,o)=setup("codex");let call=attempt("first",Kind::Model,100);invoke!(a,g,o,reserve_attempt,&call,100_009).unwrap();invoke!(a,g,o,start_attempt,&call,100_010).unwrap();let s=&g.admissions[0].spec;let proof=g.admissions[0].proof.as_ref().unwrap();a.request_stop(s,proof,super::leases::StopReason::Pause,100_011).unwrap();assert_eq!(invoke!(a,g,o,reserve_attempt,&attempt("next",Kind::Model,1),100_012).err(),Some(Failure::Revoked));invoke!(a,g,o,finish_attempt,&call,None,300_000).unwrap();}
#[test]fn over_limit_or_backwards_receipts_do_not_modify_the_original_reservation(){let(_f,a,g,_p,o)=setup("codex");let call=attempt("first",Kind::Model,100);invoke!(a,g,o,reserve_attempt,&call,100_009).unwrap();invoke!(a,g,o,start_attempt,&call,100_010).unwrap();assert_eq!(invoke!(a,g,o,finish_attempt,&call,Some(101),100_011).err(),Some(Failure::Invalid));assert_eq!(invoke!(a,g,o,finish_attempt,&call,Some(1),100_009).err(),Some(Failure::Invalid));assert_eq!(invoke!(a,g,o,output_remaining,100_012).unwrap(),3996);}
#[test]fn receipt_reconciliation_is_idempotent_and_cannot_change_unknown_usage_to_zero(){let(_f,mut a,g,_p,o)=setup("codex");let call=attempt("first",Kind::Model,100);invoke!(a,g,o,reserve_attempt,&call,100_009).unwrap();invoke!(a,g,o,start_attempt,&call,100_010).unwrap();a.fault=Fault::AfterGrantPublish;assert_eq!(invoke!(a,g,o,finish_attempt,&call,None,100_011).err(),Some(Failure::Uncertain));a.fault=Fault::None;invoke!(a,g,o,finish_attempt,&call,None,100_012).unwrap();assert_eq!(invoke!(a,g,o,finish_attempt,&call,Some(0),100_013).err(),Some(Failure::RecoveryRequired));}
#[test]fn budget_ledger_survives_reopen_and_unsigned_edits_invalidate_the_grant(){let(f,a,g,_p,o)=setup("codex");let call=attempt("first",Kind::Model,100);invoke!(a,g,o,reserve_attempt,&call,100_009).unwrap();drop(a);let a=Authority::existing(&root(&f)).unwrap();assert_eq!(invoke!(a,g,o,output_remaining,100_010).unwrap(),3996);let file=root(&f).join(format!("{}.json",g.admissions[0].spec.decision_id));let mut value:serde_json::Value=serde_json::from_slice(&std::fs::read(&file).unwrap()).unwrap();assert_eq!(value["body"]["schemaVersion"],6);value["body"]["budgetUsage"]["attempts"][0]["outputReserved"]=1.into();std::fs::write(file,serde_json::to_vec(&value).unwrap()).unwrap();assert_eq!(invoke!(a,g,o,output_remaining,100_011).err(),Some(Failure::Invalid));}
#[test]fn malformed_or_duplicate_ledger_rows_never_grant_extra_budget(){let mut ledger=Ledger::empty();let first=attempt("first",Kind::Model,1);ledger.attempts.push(first.clone());assert!(ledger.valid());ledger.attempts.push(first);assert!(!ledger.valid());let mut invalid=attempt("invalid",Kind::Model,0);assert!(!invalid.valid());invalid.output_reserved=1;invalid.phase=Phase::Settled;invalid.accepted_output=Some(0);assert!(!invalid.valid());}
